os.makedirs("logos", exist_ok=True)
total = len(companies)
ok = 0
fail = 0

for i, (ticker, domain) in enumerate(companies.items(), 1):
    path = f"logos/{ticker}.png"
    if os.path.exists(path):
        print(f"[{i}/{total}] SKIP {ticker}")
        continue
    url = f"https://t1.gstatic.com/faviconV2?client=SOCIAL&type=FAVICON&fallback_opts=TYPE,SIZE,URL&url=https://{domain}&size=128"
    try:
        urllib.request.urlretrieve(url, path)
        size = os.path.getsize(path)
        if size > 50:
            print(f"[{i}/{total}] OK {ticker}")
            ok += 1
        else:
            os.remove(path)
            print(f"[{i}/{total}] SMALL {ticker}")
            fail += 1
    except Exception as e:
        print(f"[{i}/{total}] FAIL {ticker}: {e}")
        fail += 1
    time.sleep(0.15)

print(f"\nDone: {ok} downloaded, {fail} failed")
